"""usage: leaf.py FILE (leaf N | grep PATTERN [maxhits]) [--chars N]
Prints the leaf, its numeric-only lines (candidate printed page numbers), and matches with context."""
import sys,re
args=sys.argv[1:]
chars=1500
if '--chars' in args:
    i=args.index('--chars'); chars=int(args[i+1]); del args[i:i+2]
f=args[0]; mode=args[1]
pages=open(f,encoding='utf-8',errors='replace').read().split('\f')
def nums(p):
    out=[]
    for l in p.split('\n'):
        s=l.strip()
        m=re.fullmatch(r'[—\-–\s]*(\d{1,4})[—\-–\s]*',s)
        if m: out.append(m.group(1))
        else:
            m=re.match(r'^(\d{1,4})\s+\S',s) or re.search(r'\S\s+(\d{1,4})$',s)
            if m and len(s)<90: out.append(m.group(1)+'?')
    return out
if mode=='leaf':
    n=int(args[2]); p=pages[n]
    print(f'--- {f} leaf {n} / {len(pages)}; page-number candidates: {nums(p)[:8]}')
    print(p[:chars] if chars>0 else p)
else:
    pat=args[2]; mx=int(args[3]) if len(args)>3 else 5; hits=0
    for i,p in enumerate(pages):
        for m in re.finditer(pat,p,re.M|re.I):
            hits+=1
            s=max(0,m.start()-100); e=min(len(p),m.end()+chars)
            print(f'--- {f} leaf {i}; page-number candidates: {nums(p)[:8]}')
            print(p[s:e].replace('\n',' ')); print()
            break
        if hits>=mx: break
    if not hits: print('NO HITS',pat)
